<?php
declare(strict_types=1);
require dirname(__DIR__).'/vendor/autoload.php';
use Kashf\{Calendar,Database,Learning,Backup};
$checks=0;
function eq(mixed $actual,mixed $expected,string $message):void{global $checks;$checks++;if($actual!==$expected)throw new RuntimeException($message.' expected '.json_encode($expected).' got '.json_encode($actual));}
function rejects(callable $fn,string $message):void{global $checks;$checks++;try{$fn();}catch(InvalidArgumentException){return;}throw new RuntimeException($message);}
$db=Database::connect(['dsn'=>'sqlite::memory:']);$catalog=json_decode(file_get_contents(dirname(__DIR__).'/database/catalog.json'),true,512,JSON_THROW_ON_ERROR);Database::install($db,$catalog);$l=new Learning($db);$s=$l->state('child');
eq(count($s['subjects']),7,'Seven subjects');eq(count($s['resources']),17,'Initial sources');eq(count($s['logs']),0,'No demo data');eq(count($s['completions']),0,'Starts empty');
foreach(['math'=>35,'persian'=>38,'science'=>12,'social'=>21,'religion'=>17,'quran'=>13,'kangaroo'=>18]as$subject=>$total){$rs=array_values(array_filter($s['resources'],fn($r)=>$r['subject']===$subject));foreach($rs as$r)eq(count($r['topics']),$total,'Mirrored curriculum '.$subject);}
eq(Calendar::parse('۱۴۰۳/۱۲/۳۰',true),'2025-03-20','Jalali leap day');rejects(fn()=>Calendar::parse('1404/12/30',true),'Reject non leap day');rejects(fn()=>Calendar::parse('1405/13/01',true),'Reject bad month');rejects(fn()=>Calendar::parse('2025-02-30',true),'Reject invalid Gregorian date');rejects(fn()=>Calendar::parse('2099-01-01'),'Reject future activity');
foreach(['2026-10-17','2026-10-20','2026-10-23'] as $day){$r=Calendar::range('week',$day);eq([$r['start'],$r['end']],['2026-10-10','2026-10-16'],'Full previous week from '.$day);}
$r=Calendar::range('month','2026-10-20');eq([$r['start'],$r['end']],['2026-08-23','2026-09-22'],'Previous Persian month');
$r=Calendar::range('month','2025-03-21');eq(Calendar::jalali($r['start']),'1403/12/01','Previous year boundary');eq(Calendar::jalali($r['end']),'1403/12/30','Leap month end');
$date=Calendar::today();$topic=$s['resources'][0]['topics'][0]['id'];$other=$s['resources'][0]['topics'][1]['id'];$activity=['subject'=>'math','source'=>'school','topic'=>$topic,'date'=>$date,'note'=>'تست <script>alert(1)</script>','complete'=>true];
$a=$l->activity($activity);$b=$l->activity($activity);eq(count($l->state('child')['completions']),1,'Duplicate completion counts once');
$l->activity($activity+['unused'=>'value'],$a);eq(count($l->state('child')['completions']),1,'Edit maintains dedup');$changed=$activity;$changed['topic']=$other;$l->activity($changed,$a);eq(count($l->state('child')['completions']),2,'Edit recomputes topic');$changed['complete']=false;$l->activity($changed,$a);eq(count($l->state('child')['completions']),1,'Edit removes obsolete completion');
$ai=$activity;$ai['source']='ai';$l->activity($ai);eq(count($l->state('child')['completions']),2,'AI independent');
$task=$l->assignment(['subject'=>'math','title'=>'تکلیف آزمایش','description'=>'شرح','due'=>$date]);$l->complete($task,true);eq(count($l->state('child')['completions']),2,'Task completion independent');$tasklog=$activity;$tasklog['task']=$task;$tasklog['topic']=$other;$l->activity($tasklog);eq(count($l->state('child')['completions']),2,'Task activity independent');
$old=Calendar::range('week')['start'];$extra=$l->record('extra',['subject'=>'science','title'=>'مطالعهٔ بیشتر','report'=>'گزارش اول','date'=>$old]);$l->record('extra',['subject'=>'science','title'=>'ویرایش','report'=>'گزارش دوم','date'=>$date],$extra);$l->record('challenge',['subject'=>'general','title'=>'سؤال روزمره','report'=>'گزارش','date'=>$old]);eq(count($l->state('child')['completions']),2,'Reports independent');eq($l->state('parent')['extras'][0]['date'],$old,'Edit preserves report date');eq(count($l->report('week')['extras']),1,'Old edited report remains in period');eq(count($l->report('week')['challenges']),1,'General challenges included');
$rid=$l->resource(['subject'=>'social','title'=>'منبع تازه','shared'=>true]);$custom=array_values(array_filter($l->state('parent')['resources'],fn($r)=>$r['database_id']===$rid))[0];eq(count($custom['topics']),21,'New mirrored source');$cid=$l->resource(['subject'=>'social','title'=>'فهرست خودمان','shared'=>false,'topics'=>"موضوع یک\nموضوع دو\nموضوع یک"]);eq((int)$db->query('SELECT COUNT(*) FROM resource_topics WHERE resource_id='.$cid)->fetchColumn(),2,'Custom unique topics');
$l->archive($s['resources'][0]['database_id']);eq(count($l->state('child')['completions']),2,'Archive retains completion history');rejects(fn()=>$l->activity($activity),'Archived source cannot get new activity');eq(count($l->state('child')['logs']),4,'All history retained');
$backupDir=dirname(__DIR__).'/work/backup-test-'.bin2hex(random_bytes(4));mkdir($backupDir,0700,true);$backup=new Backup($db,$backupDir);for($i=1;$i<=9;$i++)file_put_contents($backupDir.'/kashf-2020-01-'.sprintf('%02d',$i).'.json.gz','old');$backup->daily();eq(count($backup->files()),7,'Seven backup retention');$file=$backup->files()[0]['name'];$before=$l->state('child');$l->record('challenge',['subject'=>'math','title'=>'after backup','report'=>'restore should remove','date'=>$date]);Backup::restore($db,$backup->path($file));eq($l->state('child')['logs'],$before['logs'],'Restore activities');eq($l->state('child')['challenges'],$before['challenges'],'Restore reports');eq($l->state('child')['completions'],$before['completions'],'Restore progress');
foreach(glob($backupDir.'/*')as$f)unlink($f);unlink($backupDir.'/.lock');rmdir($backupDir);
